export function serialize(
  SUBS: readonly Float64Array[],
  closed?: readonly boolean[],
): string {
  let d = "";
  for (let k = 0; k < SUBS.length; k++) {
    const o = SUBS[k];
    const n = o.length / 2;
    d += `M${fmt(o[0])} ${fmt(o[1])}`;
    for (let i = 1; i < n; i++) d += `L${fmt(o[2 * i])} ${fmt(o[2 * i + 1])}`;
    if (closed?.[k]) d += "Z";
  }
  return d;
}
